    function showSoldDeal(player) {
      if (!soldDeal) return;
      var teamEl = document.getElementById('pjSoldDealTeam');
      var logoEl = document.getElementById('pjSoldDealLogo');
      var ptsEl = document.getElementById('pjSoldDealPts');
      if (teamEl) teamEl.textContent = (player && player.team_name) || '—';
      if (logoEl) {
        if (player && (player.team_logo_url || player.team_logo)) {
          logoEl.src = player.team_logo_url || ('data:image/jpeg;base64,' + player.team_logo);
          logoEl.style.display = 'block';
        } else {
          logoEl.removeAttribute('src');
          logoEl.style.display = 'none';
        }
      }
      if (ptsEl) {
        if (player && player.sold_points) {
          ptsEl.innerHTML = window.fmtUnitHtml
            ? window.fmtUnitHtml(player.sold_points, 'pj-sold-deal__pts-unit')
            : (Number(player.sold_points).toLocaleString() +
              '<span class="pj-sold-deal__pts-unit">PTS</span>');
          ptsEl.style.display = 'block';
        } else {
