      if (baseVal) {
        if (window.fmtUnit) {
          baseVal.textContent = window.fmtUnit(p.base_price);
          if (baseUnit) baseUnit.style.display = 'none';
        } else {
          baseVal.textContent = Number(p.base_price).toLocaleString();
          if (baseUnit) {
            baseUnit.textContent = (window.pointUnitSymbol && window.pointUnitSymbol()) || 'PTS';
            baseUnit.style.display = '';
          }
        }
      }
      if (baseEl) baseEl.style.display = 'inline-flex';
    } else if (baseEl) {
      baseEl.style.display = 'none';
    }
    if (p.state === 'sold') {
      showSoldDeal(p);
    } else {
      hideSoldDeal();
    }

    var stampWrap = document.getElementById('pjStampWrap');
    var soldTeam = document.getElementById('pjSoldTeam');
    var photoStatus = document.getElementById('pjPhotoStatus');
    var photoSold = document.getElementById('pjPhotoSold');
    var photoSide = document.getElementById('pjPhotoSide');
    if (typeof window._pjSealFadeTimer === 'undefined') window._pjSealFadeTimer = null;
    function reAnim(el){ if(!el) return; el.style.animation='none'; void el.offsetHeight; el.style.animation=''; }
    function clearSealFade() {
      if (window._pjSealFadeTimer) {
        clearTimeout(window._pjSealFadeTimer);
        window._pjSealFadeTimer = null;
      }
      if (photoStatus) photoStatus.classList.remove('is-faded');
      if (photoSold) photoSold.classList.remove('is-faded');
    }
    function scheduleStampFade() {
      clearSealFade();
      window._pjSealFadeTimer = setTimeout(function() {
        if (photoStatus && photoStatus.classList.contains('show')) {
          photoStatus.classList.add('is-faded');
        }
        if (photoSold && photoSold.classList.contains('show')) {
          photoSold.classList.add('is-faded');
        }
        window._pjSealFadeTimer = null;
      }, 3000);
    }
    function hidePhotoSold() {
      if (!photoSold) return;
      photoSold.classList.remove('show', 'is-faded');
    }
    function showMysterySoldRibbon(player) {
      if (!photoSold) return;
      var nameEl = document.getElementById('pjPhotoSoldName');
      var logoEl = document.getElementById('pjPhotoSoldLogo');
      var ptsEl = document.getElementById('pjPhotoSoldPts');
      if (nameEl) nameEl.textContent = (player && player.team_name) || '';
      if (logoEl) {
        if (player && (player.team_logo_url || player.team_logo)) {
          logoEl.src = player.team_logo_url || ('data:image/jpeg;base64,' + player.team_logo);
          logoEl.style.display = 'block';
        } else {
          logoEl.removeAttribute('src');
          logoEl.style.display = 'none';
        }
      }
      if (ptsEl) {
        if (player && player.sold_points) {
          ptsEl.textContent = 'for ' + (window.fmtUnit
            ? window.fmtUnit(player.sold_points)
            : (Number(player.sold_points).toLocaleString() + ' pts'));
          ptsEl.style.display = 'block';
        } else {
          ptsEl.textContent = '';
          ptsEl.style.display = 'none';
        }
      }
      photoSold.classList.remove('is-faded');
      photoSold.style.animation = 'none';
      void photoSold.offsetHeight;
      photoSold.style.animation = '';
      var ribbon = photoSold.querySelector('.pj-photo-sold-ribbon');
      if (ribbon) {
        ribbon.style.animation = 'none';
        void ribbon.offsetHeight;
        ribbon.style.animation = '';
      }
      photoSold.classList.add('show');
      scheduleStampFade();
    }
    function hidePhotoStatus() {
      if (!photoStatus) return;
      photoStatus.classList.remove('show', 'is-faded');
      if (photoSide) {
        photoSide.classList.remove('is-status-freeze', 'is-sold-glow', 'is-unsold-shake');
      }
    }
    function showPhotoStatus(kind, player, playSound) {
      if (!photoStatus) return;
      var isSold = kind === 'sold';
      var wordEl = document.getElementById('pjStatusWord');
      var icoEl = document.getElementById('pjStatusIco');
      var teamEl = document.getElementById('pjStatusSealTeam');
      var ptsEl = document.getElementById('pjStatusSealPts');
      var logoEl = document.getElementById('pjStatusSealLogo');
      var arcTop = document.getElementById('pjSealArcTopText');
      var arcBot = document.getElementById('pjSealArcBotText');
      var ribbon = document.getElementById('pjPhotoStatusRibbon');
      var seal = document.getElementById('pjStatusSeal');
      var fx = document.getElementById('pjStatusFx');
      var glow = photoStatus.querySelector('.pj-status-glow');

      photoStatus.setAttribute('data-kind', isSold ? 'sold' : 'unsold');
      if (wordEl) wordEl.textContent = isSold ? 'SOLD' : 'UNSOLD';
      if (icoEl) icoEl.textContent = isSold ? '✓' : '✕';
      if (arcTop) {
        var tp = arcTop.querySelector('textPath');
        if (tp) tp.textContent = isSold ? '★★★ SOLD TO ★★★' : '★★★ NO BID ★★★';
      }
      if (arcBot) {
        var bp = arcBot.querySelector('textPath');
        if (bp) bp.textContent = isSold ? '★★★★★' : 'UNSOLD';
      }
      if (teamEl) teamEl.textContent = (isSold && player && player.team_name) ? player.team_name : '';
      if (logoEl) {
        if (isSold && player && (player.team_logo_url || player.team_logo)) {
          logoEl.src = player.team_logo_url || ('data:image/jpeg;base64,' + player.team_logo);
          logoEl.classList.add('is-on');
        } else {
          logoEl.removeAttribute('src');
          logoEl.classList.remove('is-on');
        }
      }
      if (ptsEl) {
        if (isSold && player && player.sold_points) {
          ptsEl.textContent = window.fmtUnit
            ? window.fmtUnit(player.sold_points)
            : (Number(player.sold_points).toLocaleString() + ' PTS');
          ptsEl.style.display = '';
        } else {
          ptsEl.textContent = '';
          ptsEl.style.display = 'none';
        }
      }

      /* Replay premium broadcast sequence */
      clearSealFade();
      photoStatus.classList.remove('show', 'is-faded');
      if (photoSide) {
        photoSide.classList.remove('is-status-freeze', 'is-sold-glow', 'is-unsold-shake');
        void photoSide.offsetHeight;
        photoSide.classList.add('is-status-freeze');
        if (isSold) photoSide.classList.add('is-sold-glow');
        else photoSide.classList.add('is-unsold-shake');
      }
      void photoStatus.offsetHeight;
      [glow, seal, ribbon, fx].forEach(reAnim);
      if (fx) Array.prototype.forEach.call(fx.children, reAnim);
      photoStatus.classList.add('show');
      scheduleStampFade();
      if (playSound) playPjStatusSound(isSold ? 'sold' : 'unsold', player);
    }
    /* Status graphics live only on the player photograph */
    if (stampWrap) stampWrap.classList.remove('show');
    if (soldTeam) {
      soldTeam.classList.remove('show');
      soldTeam.style.display = 'none';
    }
    if (opts.skipStatusStamp || opts.mysteryRevealIntro) {
      /* Mystery reveal: refresh photo/name only — do not replay SOLD overlay */
      hidePhotoSold();
      hidePhotoStatus();
      clearSealFade();
    } else if (p.state === 'sold') {
      hidePhotoSold();
      showPhotoStatus('sold', p, !!opts.playStatusSound);
    } else if (p.state === 'unsold') {
      hidePhotoSold();
      showPhotoStatus('unsold', p, !!opts.playStatusSound);
    } else {
      hidePhotoSold();
      hidePhotoStatus();
      clearSealFade();
    }
    updateStatusRibbon(p);

    if (isRevealIntro) {
      playMysteryRevealIntro(function () {
        var n = document.getElementById('pjName');
        if (n) {
          n.textContent = p.name || '';
          n.style.opacity = '';
        }
      });
    }
  }

  function showCard(p, opts) {
    opts = opts || {};
    document.getElementById('pj-waiting').classList.add('hidden');
    var card = document.getElementById('pj-card');
    var fromWaiting = !card.classList.contains('visible');
    card.classList.add('pj-exit');
    card.classList.remove('visible');
    var delay = fromWaiting ? 40 : 160;
    setTimeout(function() {
      card.classList.remove('pj-exit');
      try { renderPlayer(p, opts); } catch(e) { console.error('[Projector] renderPlayer error:', e); }
      card.classList.add('visible');
    }, delay);
  }

  function showWaiting() {
    hideMysteryRevealIntro();
    document.getElementById('pj-card').classList.remove('visible');
    document.getElementById('pj-card').classList.add('pj-exit');
    var badge = document.getElementById('pjSerialBadge');
    if (badge) badge.style.display = 'none';
    updateStatusRibbon(null);
    setTimeout(function() {
      document.getElementById('pj-waiting').classList.remove('hidden');
    }, 200);
  }

  var _currentWaitPhase = null;
  var _pjTyConfettiBuilt = false;
  function buildPjTyConfetti() {
    var box = document.getElementById('pjTyConfetti');
    if (!box || _pjTyConfettiBuilt) return;
    var colors = ['#ffd700', '#ffe08a', '#fff', '#f5c842', '#ffb347', '#e8c200'];
    var html = '';
    for (var i = 0; i < 28; i++) {
      var left = Math.round(Math.random() * 100);
      var delay = (Math.random() * 4).toFixed(2);
      var dur = (3.5 + Math.random() * 3.5).toFixed(2);
      var dx = Math.round(-40 + Math.random() * 80);
      var color = colors[i % colors.length];
      html += '<span class="pj-ty-piece" style="left:' + left + '%;background:' + color +
        ';animation-delay:' + delay + 's;animation-duration:' + dur + 's;--dx:' + dx + 'px"></span>';
    }
    box.innerHTML = html;
    _pjTyConfettiBuilt = true;
  }
  function replayPjTyCeremony() {
    var wait = document.getElementById('pj-waiting');
    if (!wait) return;
    wait.classList.add('pj-ty-replay');
    void wait.offsetWidth;
    wait.classList.remove('pj-ty-replay');
  }
  function updateWaitPhase(wp) {
    wp = wp || {};
    var phase = wp.phase || 'waiting';
    var msg = wp.message || 'THE SPOTLIGHT MOVES TO THE NEXT PLAYER';
    var tourName = wp.tournament_name || '';
    var sub = document.getElementById('pjWaitSub');
    var wait = document.getElementById('pj-waiting');
    var kicker = wait ? wait.querySelector('.pj-wait-kicker') : null;
    var ceremony = document.getElementById('pjCompleteCeremony');
    var tyMsg = document.getElementById('pjTyMessage');
    var tyTour = document.getElementById('pjTyTourName');
    var enteringComplete = phase === 'completed' && _currentWaitPhase !== 'completed';

    if (sub) {
      sub.textContent = msg;
      sub.classList.toggle('is-begin', phase === 'about_to_begin');
      sub.classList.toggle('is-complete', phase === 'completed');
    }
    if (wait) wait.classList.toggle('is-complete', phase === 'completed');
    if (ceremony) ceremony.setAttribute('aria-hidden', phase === 'completed' ? 'false' : 'true');
    if (tyMsg && phase === 'completed') tyMsg.textContent = msg;
    if (tyTour) tyTour.textContent = phase === 'completed' && tourName ? tourName : '';
    var tyLogoWrap = document.getElementById('pjTyLogoWrap');
    if (tyLogoWrap) {
      var hasLogo = !!tyLogoWrap.querySelector('img');
      tyLogoWrap.classList.toggle('is-on', phase === 'completed' && hasLogo);
    }
    if (kicker) {
      if (phase === 'about_to_begin') kicker.textContent = 'Live Auction · Stand By';
      else if (phase === 'completed') kicker.textContent = 'Auction Complete';
      else kicker.textContent = 'Live Auction · Stand By';
    }
    if (phase === 'completed') {
      buildPjTyConfetti();
      if (enteringComplete) replayPjTyCeremony();
    }
    _currentWaitPhase = phase;
  }

  var _pjPollInFlight = false;
  var _pjPollIdle = 2000;
  var _pjPollBurst = 400;
  var _pjBurstUntil = 0;
  var _pjLastFp = '';
  function pjPollDelay() {
    return (Date.now() < _pjBurstUntil) ? _pjPollBurst : _pjPollIdle;
  }
  function schedulePjPoll() {
    clearTimeout(_pollTimer);
    _pollTimer = setTimeout(poll, pjPollDelay());
  }
  function armPjBurst() {
    _pjBurstUntil = Date.now() + 6000;
  }
  function poll() {
    if (_pjPollInFlight) return;
    _pjPollInFlight = true;
    fetch(window.PJ_DATA_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc:'2.0',method:'call',params:{}}),
      cache: 'no-store'
    })
    .then(function(r){ return r.json(); })
    .then(function(json) {
      var result = json.result || {};
      var p = result.player;
      var d0 = result.dice || {};
      var fp = [
        (p && p.id) || 0,
        (p && p.state) || '',
        (p && p.current_bid) || 0,
        (p && p.sold_points) || 0,
        !!((p && p.mystery_revealed)),
        d0.state || '',
        d0.result || 0,
        result.break_time ? 1 : 0,
        (result.wait_phase && result.wait_phase.phase) || '',
        (result.boards && result.boards.sig) || ''
      ].join('|');
      if (_pjLastFp && fp !== _pjLastFp) armPjBurst();
      _pjLastFp = fp;
      var d = result.dice || {state:'idle', result:0, is_mystery:false};
      handlePjBreak(!!result.break_time);
      updatePjBreakAds(result.advertisers || []);
      var waitPhase = result.wait_phase || {};
      var boards = result.boards || {};
      // Declare Auction Complete / Thank You must override pool & fixture boards
      if (waitPhase.phase === 'completed') {
        boards = Object.assign({}, boards, {
          mode: 'idle',
          revealing: false,
          sig: (boards.sig || '') + '|thankyou'
        });
      }
      updatePjBoards(boards);
      updateProgress(result.progress);
      updateTeamsStrip(result.teams);
      updateBids(result.recent_bids);
      updatePurse(result.top_purse);
      updateAuctionMeta(result.auction_meta);
      if (typeof window._pjOnPollResult === 'function') {
        try { window._pjOnPollResult(result); } catch (e) {}
      }
      maybeRefreshPjSquad(p);

      if (!p) {
        if (_currentId !== null) {
          _currentId = null; _currentState = null; _currentPts = null; _currentMysteryRevealed = null;
          showWaiting();
        }
        updateWaitPhase(waitPhase);
        if (waitPhase.phase === 'completed') {
          try { closePjBoard(false); } catch (eDone) {}
          try { closePjSquad(); } catch (eSq) {}
          try { closePjRemain(); } catch (eRm) {}
        }
        if (d.state !== _currentDice || d.result !== _currentDiceNum || !!d.is_mystery !== !!_currentDiceMystery) {
          _currentDice = d.state; _currentDiceNum = d.result; _currentDiceMystery = !!d.is_mystery;
          updatePjDice(d.state, d.result, !!d.is_mystery);
        }
        return;
      }
      if (_currentDice !== 'idle') { _currentDice = 'idle'; _currentDiceNum = 0; _currentDiceMystery = false; hidePjDice(); }
      var revealOnly = (
        p.id === _currentId &&
        p.state === _currentState &&
        p.state === 'sold' &&
        !_currentMysteryRevealed &&
        !!p.mystery_revealed
      );
      if (p.id !== _currentId || p.state !== _currentState || (p.sold_points || 0) !== _currentPts
          || !!p.mystery_revealed !== !!_currentMysteryRevealed) {
        var prevId = _currentId;
        var prevState = _currentState;
        /* Fire on any transition into sold/unsold (same player auction→sold, or stamp). */
        var playStatusSound = !revealOnly
          && (p.state === 'sold' || p.state === 'unsold')
          && prevState !== p.state;
        _currentId = p.id; _currentState = p.state; _currentPts = p.sold_points || 0;
        _currentMysteryRevealed = !!p.mystery_revealed;
        showCard(p, revealOnly
          ? {skipStatusStamp: true, mysteryRevealIntro: true}
          : {playStatusSound: playStatusSound});
      } else {
        updateStatusRibbon(p);
      }
    })
    .catch(function(e){ console.error('[Projector] poll error:', e); })
    .then(function() { _pjPollInFlight = false; schedulePjPoll(); });
  }

  function tickClock() {
    var el = document.getElementById('pjClock');
    if (!el) return;
    var d = new Date();
    var h = d.getHours(), m = d.getMinutes();
    var ampm = h >= 12 ? 'PM' : 'AM';
    h = h % 12; if (!h) h = 12;
    el.textContent = h + ':' + (m < 10 ? '0' : '') + m + ' ' + ampm;
  }

  poll();
  setPjDiceFace(1);
  tickClock();
  setInterval(tickClock, 15000);

  /* Warm browser cache for remaining auction photos so next player appears instantly.
     Stage cards use sz=pj; remaining board uses full photos — preload BOTH. */
  var _pjPreloadedUrls = Object.create(null);
  var _pjPreloadBusy = false;
  function pjStagePhotoUrl(url) {
    if (!url) return '';
    if (url.indexOf('sz=pj') >= 0) return url;
    return url + (url.indexOf('?') >= 0 ? '&' : '?') + 'sz=pj';
  }
  function preloadRemainingPhotos() {
    if (_pjPreloadBusy || !window.PJ_REMAIN_URL) return;
    _pjPreloadBusy = true;
    fetch(window.PJ_REMAIN_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}}),
      cache: 'no-store'
    })
    .then(function(r) { return r.json(); })
    .then(function(json) {
      var data = json.result || {};
      var players = data.players || [];
      var queue = [];
      for (var i = 0; i < players.length; i++) {
        var url = players[i] && players[i].photo_url;
        if (!url) continue;
        var stageUrl = pjStagePhotoUrl(url);
        if (!_pjPreloadedUrls[stageUrl]) {
          _pjPreloadedUrls[stageUrl] = 1;
          queue.push(stageUrl);
        }
        if (!_pjPreloadedUrls[url]) {
          _pjPreloadedUrls[url] = 1;
          queue.push(url);
        }
      }
      var idx = 0;
      var active = 0;
      var maxParallel = 3;
      function pump() {
        while (active < maxParallel && idx < queue.length) {
          (function(u) {
            active++;
            var im = new Image();
            im.decoding = 'async';
            var done = function() { active--; pump(); };
            im.onload = done;
            im.onerror = done;
            im.src = u;
          })(queue[idx++]);
        }
      }
      pump();
    })
    .catch(function() {})
    .then(function() { _pjPreloadBusy = false; });
  }
