  window.pjSponScroll = function(){};
  /* Sponsors stay centered and stationary — no marquee */

  function pjFsElement() {
    return document.fullscreenElement
      || document.webkitFullscreenElement
      || document.mozFullScreenElement
      || document.msFullscreenElement
      || null;
  }
  function pjRequestFullscreen(el) {
    if (!el) return Promise.reject(new Error('No element'));
    if (el.requestFullscreen) return el.requestFullscreen();
    if (el.webkitRequestFullscreen) return Promise.resolve(el.webkitRequestFullscreen());
    if (el.mozRequestFullScreen) return Promise.resolve(el.mozRequestFullScreen());
    if (el.msRequestFullscreen) return Promise.resolve(el.msRequestFullscreen());
    return Promise.reject(new Error('Fullscreen unsupported'));
  }
  function pjExitFullscreen() {
    if (document.exitFullscreen) return document.exitFullscreen();
    if (document.webkitExitFullscreen) return Promise.resolve(document.webkitExitFullscreen());
    if (document.mozCancelFullScreen) return Promise.resolve(document.mozCancelFullScreen());
    if (document.msExitFullscreen) return Promise.resolve(document.msExitFullscreen());
    return Promise.reject(new Error('Exit fullscreen unsupported'));
  }
  function pjSyncFsBtn() {
    var btn = document.getElementById('pjFsBtn');
    var root = document.getElementById('pj-root');
    var active = !!pjFsElement();
    if (root) root.classList.toggle('is-fs', active);
    if (!btn) return;
    btn.classList.toggle('is-fs', active);
    btn.title = active ? 'Exit Fullscreen' : 'Fullscreen';
    btn.setAttribute('aria-label', btn.title);
    var exitIco = btn.querySelector('.pj-fs-ico--exit');
    var enterIco = btn.querySelector('.pj-fs-ico--enter');
    if (exitIco) {
      if (active) exitIco.removeAttribute('hidden');
      else exitIco.setAttribute('hidden', 'hidden');
    }
    if (enterIco) {
      if (active) enterIco.setAttribute('hidden', 'hidden');
      else enterIco.removeAttribute('hidden');
    }
  }
  window.pjToggleFs = function() {
    var active = pjFsElement();
    var target = document.documentElement;
    var p = active ? pjExitFullscreen() : pjRequestFullscreen(target);
    if (p && typeof p.then === 'function') {
      p.then(pjSyncFsBtn).catch(function(err) {
        console.warn('Projector fullscreen failed:', err);
      });
    } else {
      setTimeout(pjSyncFsBtn, 50);
    }
  };
  document.addEventListener('fullscreenchange', pjSyncFsBtn);
  document.addEventListener('webkitfullscreenchange', pjSyncFsBtn);
  document.addEventListener('mozfullscreenchange', pjSyncFsBtn);
  document.addEventListener('MSFullscreenChange', pjSyncFsBtn);
  pjSyncFsBtn();

  var _pjBreakActive = false;
  var _pjBreakStart = null;
  var _pjBreakClock = null;
  var _pjAdList = [];
  var _pjAdSig = '';
  var _pjAdTimer = null;
  var _pjAdPairIndex = 0;
  var _pjAdPairCount = 0;

  function fmtPjBreakElapsed(ms) {
    var s = Math.floor(ms / 1000);
    var m = Math.floor(s / 60);
    s = s % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }
  function startPjBreakClock() {
    stopPjBreakClock();
    _pjBreakClock = setInterval(function() {
      var el = document.getElementById('pjBrkTimer');
      if (!el || !_pjBreakStart) return;
      el.textContent = 'Break · ' + fmtPjBreakElapsed(Date.now() - _pjBreakStart);
    }, 1000);
  }
  function stopPjBreakClock() {
    if (_pjBreakClock) { clearInterval(_pjBreakClock); _pjBreakClock = null; }
  }

  function pjAdsSignature(ads) {
    return (ads || []).map(function(a) {
      return String(a.id || '') + '|' + String(a.image_url || '') + '|' + String(a.name || '');
    }).join('||');
  }
  function pjAdCellHtml(ad) {
    if (!ad) return '<div class="pj-brk-ad-cell" aria-hidden="true"></div>';
    var inner = ad.image_url
      ? '<img src="' + ad.image_url + '" alt="' + (ad.name || '') + '" onerror="this.style.display=\'none\'">'
      : '<span class="pj-brk-ad-name">' + (ad.name || '') + '</span>';
    return '<div class="pj-brk-ad-cell">' + inner + '</div>';
  }
  function goToPjAdPair(idx) {
    if (_pjAdPairCount < 1) return;
    _pjAdPairIndex = ((idx % _pjAdPairCount) + _pjAdPairCount) % _pjAdPairCount;
    var track = document.getElementById('pjBrkAdsTrack');
    var vp = document.getElementById('pjBrkAdsViewport');
    var w = vp ? vp.clientWidth : 0;
    if (track && w) track.style.transform = 'translateX(-' + (_pjAdPairIndex * w) + 'px)';
    var dots = document.querySelectorAll('#pjBrkAdsDots .pj-brk-ad-dot');
    for (var i = 0; i < dots.length; i++) dots[i].classList.toggle('active', i === _pjAdPairIndex);
  }
  function advancePjAdPair() {
    if (_pjAdPairCount < 2) return;
    goToPjAdPair(_pjAdPairIndex + 1);
  }
  function startPjAdPairTimer() {
    if (_pjAdTimer) { clearInterval(_pjAdTimer); _pjAdTimer = null; }
    if (_pjAdPairCount > 1) _pjAdTimer = setInterval(advancePjAdPair, 2000);
  }
  function buildPjAdPairs(list) {
    var n = (list || []).length;
    if (!n) return [];
    if (n === 1) return [{ a: list[0], b: null, solo: true }];
    var pairs = [];
    for (var i = 0; i < n; i += 2) {
      if (i + 1 < n) {
        pairs.push({ a: list[i], b: list[i + 1], solo: false });
      } else {
        /* Odd leftover: pair last with first (round-robin), never show a lone slot */
        pairs.push({ a: list[i], b: list[0], solo: false });
      }
    }
    return pairs;
  }
  function updatePjBreakAds(ads) {
    var next = ads || [];
    var sig = pjAdsSignature(next);
    if (sig === _pjAdSig) return;
    _pjAdList = next;
    _pjAdSig = sig;
    var wrap = document.getElementById('pjBrkAds');
    var track = document.getElementById('pjBrkAdsTrack');
    var dotsEl = document.getElementById('pjBrkAdsDots');
    if (!track) return;
    var pairs = buildPjAdPairs(_pjAdList);
    _pjAdPairCount = pairs.length;
    track.innerHTML = pairs.map(function(pair) {
      if (pair.solo) {
        return '<div class="pj-brk-ad-pair pj-brk-ad-pair-solo">' + pjAdCellHtml(pair.a) + '</div>';
      }
      return '<div class="pj-brk-ad-pair">' + pjAdCellHtml(pair.a) + pjAdCellHtml(pair.b) + '</div>';
    }).join('');
    _pjAdPairIndex = 0;
    if (dotsEl) {
      dotsEl.innerHTML = '';
      for (var d = 0; d < _pjAdPairCount; d++) {
        dotsEl.innerHTML += '<div class="pj-brk-ad-dot' + (d === 0 ? ' active' : '') + '"></div>';
      }
      dotsEl.style.display = _pjAdPairCount > 1 ? '' : 'none';
    }
    if (wrap) wrap.style.display = _pjAdList.length ? '' : 'none';
    requestAnimationFrame(function() { goToPjAdPair(0); });
    startPjAdPairTimer();
  }
  window.addEventListener('resize', function() {
    if (_pjAdPairCount) goToPjAdPair(_pjAdPairIndex);
  });

  function handlePjBreak(isBreak) {
    var overlay = document.getElementById('pjBreakOverlay');
    if (!overlay) return;
    if (isBreak) {
      if (!_pjBreakActive) {
        _pjBreakActive = true;
        _pjBreakStart = Date.now();
        overlay.classList.add('active');
        startPjBreakClock();
        try { closePjSquad(); } catch (e) {}
        // Keep live pool/fixture board above break when publishing
        // Ensure slider width is correct once overlay is visible
        requestAnimationFrame(function() {
          if (_pjAdPairCount) goToPjAdPair(_pjAdPairIndex);
          startPjAdPairTimer();
        });
      }
    } else if (_pjBreakActive) {
      _pjBreakActive = false;
      _pjBreakStart = null;
      overlay.classList.remove('active');
      stopPjBreakClock();
      if (_pjAdTimer) { clearInterval(_pjAdTimer); _pjAdTimer = null; }
      var timerEl = document.getElementById('pjBrkTimer');
      if (timerEl) timerEl.textContent = '\u25cf Break in progress';
    }
  }

  var _pjBoardSig = '';
