  var _pjBoardColors = ['#1a4f9c', '#0e6e8c', '#1e5a8a', '#2456a8', '#17607a', '#2a4d8f', '#0f5575', '#1c4580'];

  function pjEsc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function isPjBoardOpen() {
