    var poolBtn = document.getElementById('pjPoolBtn');
    var fixBtn = document.getElementById('pjFixBtn');
    if (poolBtn) poolBtn.classList.remove('is-live');
    if (fixBtn) fixBtn.classList.remove('is-live');
    if (persist) {
      // Keep closed even if a poll arrives before boards/close commits
      _pjBoardUserClosed = true;
      _pjBoardSig = '';
      if (window.PJ_BOARD_CLOSE_URL) {
        fetch(window.PJ_BOARD_CLOSE_URL, {
